let name = String::from("Sam");
let other = name; // ownership of the String moves to `other`

println!("{}", name); // compile error: `name`'s value was moved into `other`

use std::thread;

fn send_to_thread<T: Send>(value: T) {
    thread::spawn(move || {
        // `value` is now owned by the new thread; the compiler only
        // accepts this call if T is marked Send.
        drop(value);
    });
}

let x = 5;
let y = x;           // i32 is Copy: this copies the value

println!("{} {}", x, y); // both fine — x was never invalidated

let s1 = String::from("hi");
let s2 = s1.clone(); // explicit, visible deep copy

println!("{} {}", s1, s2); // both fine

struct Ticket {
    label: String,
}

impl Drop for Ticket {
    fn drop(&mut self) {
        println!("tearing up ticket: {}", self.label);
    }
}

fn main() {
    let a = Ticket { label: String::from("A") };
    let b = Ticket { label: String::from("B") };
    println!("holding both tickets");
} // b is dropped first, then a — reverse declaration order

fn calculate_length(s: &String) -> usize {
    s.len()
} // s goes out of scope here, but it doesn't own the String, so nothing is dropped

fn main() {
    let s1 = String::from("hello");
    let len = calculate_length(&s1); // borrow s1, don't move it

    println!("The length of '{}' is {}.", s1, len); // s1 still valid here
}

fn main() {
    let mut s = String::from("hello");
    let r1 = &mut s;
    let r2 = &mut s;      // error[E0499]: cannot borrow `s` as mutable more than once at a time

    println!("{}, {}", r1, r2);
}

fn dangle() -> &String {   // error[E0106]: missing lifetime specifier
    let s = String::from("hello");
    &s
} // s is dropped here — the reference above would point at freed memory

fn main() {
    let mut s = String::from("hello");

    let r1 = &s;
    let r2 = &s;
    println!("{} and {}", r1, r2);   // r1, r2's last use — their borrow ends here (NLL)

    let r3 = &mut s;                  // fine: no shared borrow is still active
    r3.push_str(", world");
    println!("{}", r3);
}

fn longest(x: &str, y: &str) -> &str {   // error[E0106]: missing lifetime specifier
    if x.len() > y.len() { x } else { y }
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() { x } else { y }
}

fn main() {
    let s1 = String::from("long string is long");
    let result;
    {
        let s2 = String::from("short");
        result = longest(s1.as_str(), s2.as_str());
        println!("longest: {}", result); // fine — s2 is still alive here
    }
    // println!("{}", result); // would be a compile error: s2 (and its borrow) is gone
}

struct ImportantExcerpt<'a> {
    part: &'a str,
}

fn main() {
    let novel = String::from("Call me Ishmael. Some years ago...");
    let first_sentence = novel.split('.').next().expect("no '.' found");
    let excerpt = ImportantExcerpt { part: first_sentence };
    println!("{}", excerpt.part); // fine — novel is still alive
}

fn first_word(s: &str) -> &str {
    match s.find(' ') {
        Some(i) => &s[..i],
        None => s,
    }
} // no 'a written anywhere — elision rule 2 assigns the single input's
  // lifetime to the elided output automatically
